mapper.select:
SELECT * FROM (
    SELECT T.*, ROWNUM RN FROM (
        SELECT id, label, icon, page_title, page_src, sort_order, is_divider, status, created_at, updated_at
        FROM sys_menus

            is_deleted = 0

                AND label LIKE '%' || #{keyword} || '%'

            AND status = #{status}

        ORDER BY sort_order ASC, created_at ASC
    ) T WHERE ROWNUM <= #{offset} + #{size}
) WHERE RN > #{offset}

mapper.update:
UPDATE sys_menus
parent_id = #{parentId}, label = #{label}, icon = #{icon}, page_title = #{pageTitle}, page_src = #{pageSrc}, sort_order = #{sortOrder}, is_divider = #{isDivider}, status = #{status}, updated_at = SYSTIMESTAMP, updated_by = #{updatedBy}
WHERE id = #{id} AND updated_at = #{updatedAt}

UPDATE sys_menus
SET is_deleted = 1, updated_at = SYSTIMESTAMP, updated_by = #{updatedBy}
WHERE id = #{id} AND updated_at = #{updatedAt}

UPDATE sys_menus
SET status = #{status},
    updated_at = SYSTIMESTAMP,
    updated_by = #{updatedBy}
WHERE id = #{id} AND updated_at = #{updatedAt}
